:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #8a8a9a;
  --snake: #4ecca3;
  --food: #e94560;
  --grid: #0f3460;
  --btn-bg: #0f3460;
  --btn-hover: #1a4a7a;
  --btn-active: #0a2647;
  --focus: #4ecca3;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.game-card {
  background: var(--card);
  border-radius: 16px;
  padding: 24px;
  width: 100%;
  max-width: 460px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

header {
  text-align: center;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: 1px;
  color: var(--snake);
}

.subtitle {
  font-size: 0.95rem;
  color: var(--muted);
  margin-top: 4px;
}

.hud {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 12px;
  background: var(--bg);
  border-radius: 8px;
}

.score-label {
  font-size: 0.9rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.score-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--snake);
  font-variant-numeric: tabular-nums;
}

.canvas-wrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  border-radius: 8px;
  overflow: hidden;
  background: var(--grid);
}

canvas {
  display: block;
  width: 100%;
  height: 100%;
  image-rendering: pixelated;
}

.overlay {
  position: absolute;
  inset: 0;
  background: rgba(26, 26, 46, 0.88);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  text-align: center;
  transition: opacity 0.2s ease;
}

.overlay.hidden {
  display: none;
}

.overlay-content {
  display: flex;
  flex-direction: column;
  gap: 12px;
  align-items: center;
}

.overlay-content h2 {
  font-size: 1.4rem;
  color: var(--snake);
}

.overlay-content p {
  font-size: 0.95rem;
  line-height: 1.5;
  color: var(--text);
  max-width: 280px;
}

.overlay-content strong {
  color: var(--accent);
}

.controls {
  display: flex;
  gap: 12px;
}

.btn {
  flex: 1;
  padding: 12px 16px;
  font-size: 1rem;
  font-family: inherit;
  font-weight: 600;
  color: var(--text);
  background: var(--btn-bg);
  border: 2px solid transparent;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease, border-color 0.15s ease;
  min-height: 48px;
  touch-action: manipulation;
}

.btn:hover {
  background: var(--btn-hover);
}

.btn:active {
  background: var(--btn-active);
  transform: scale(0.97);
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.btn.primary {
  background: var(--accent);
  color: #fff;
}

.btn.primary:hover {
  background: #d63a52;
}

.btn.primary:active {
  background: #b52e44;
}

@media (max-width: 400px) {
  .game-card {
    padding: 16px;
    gap: 12px;
  }
  h1 {
    font-size: 1.4rem;
  }
  .overlay-content p {
    font-size: 0.9rem;
  }
}

(function () {
  'use strict';

  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const overlay = document.getElementById('overlay');
  const overlayTitle = document.getElementById('overlay-title');
  const overlayText = document.getElementById('overlay-text');
  const overlayBtn = document.getElementById('overlay-btn');
  const pauseBtn = document.getElementById('pause-btn');
  const restartBtn = document.getElementById('restart-btn');

  const COLS = 20;
  const ROWS = 20;
  const CELL = canvas.width / COLS;
  const TICK_MS = 120;

  let snake, dir, nextDir, food, score, state, timer;
  // state: 'paused' | 'playing' | 'over'

  function reset() {
    snake = [{ x: 10, y: 10 }, { x: 9, y: 10 }, { x: 8, y: 10 }];
    dir = { x: 1, y: 0 };
    nextDir = { x: 1, y: 0 };
    score = 0;
    scoreEl.textContent = '0';
    placeFood();
    draw();
  }

  function placeFood() {
    let pos;
    do {
      pos = { x: Math.floor(Math.random() * COLS), y: Math.floor(Math.random() * ROWS) };
    } while (snake.some(s => s.x === pos.x && s.y === pos.y));
    food = pos;
  }

  function start() {
    if (state === 'playing') return;
    state = 'playing';
    overlay.classList.add('hidden');
    pauseBtn.textContent = 'Pause';
    clearInterval(timer);
    timer = setInterval(step, TICK_MS);
  }

  function pause() {
    if (state !== 'playing') return;
    state = 'paused';
    clearInterval(timer);
    pauseBtn.textContent = 'Resume';
    showOverlay('Paused', 'Press Resume or an arrow key to continue.', 'Resume');
  }

  function gameOver() {
    state = 'over';
    clearInterval(timer);
    pauseBtn.textContent = 'Pause';
    showOverlay('Game Over', 'Your score: ' + score + '. Press Restart to play again.', 'Restart');
  }

  function showOverlay(title, text, btnLabel) {
    overlayTitle.textContent = title;
    overlayText.innerHTML = text;
    overlayBtn.textContent = btnLabel;
    overlay.classList.remove('hidden');
  }

  function step() {
    dir = nextDir;
    const head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };

    if (head.x < 0 || head.x >= COLS || head.y < 0 || head.y >= ROWS) {
      return gameOver();
    }
    if (snake.some(s => s.x === head.x && s.y === head.y)) {
      return gameOver();
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
      score += 10;
      scoreEl.textContent = String(score);
      placeFood();
    } else {
      snake.pop();
    }

    draw();
  }

  function draw() {
    ctx.fillStyle = getComputedStyle(document.documentElement).getPropertyValue('--grid').trim() || '#0f3460';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // food
    ctx.fillStyle = getComputedStyle(document.documentElement).getPropertyValue('--food').trim() || '#e94560';
    ctx.fillRect(food.x * CELL + 1, food.y * CELL + 1, CELL - 2, CELL - 2);

    // snake
    ctx.fillStyle = getComputedStyle(document.documentElement).getPropertyValue('--snake').trim() || '#4ecca3';
    for (let i = 0; i < snake.length; i++) {
      const s = snake[i];
      ctx.fillRect(s.x * CELL + 1, s.y * CELL + 1, CELL - 2, CELL - 2);
    }
  }

  function setDirection(nx, ny) {
    // prevent reversing directly
    if (nx === -dir.x && ny === -dir.y) return;
    nextDir = { x: nx, y: ny };
    if (state === 'paused') start();
  }

  document.addEventListener('keydown', function (e) {
    const key = e.key;
    if (key === 'ArrowUp' || key === 'ArrowDown' || key === 'ArrowLeft' || key === 'ArrowRight') {
      e.preventDefault();
      if (state === 'over') return;
      if (key === 'ArrowUp') setDirection(0, -1);
      else if (key === 'ArrowDown') setDirection(0, 1);
      else if (key === 'ArrowLeft') setDirection(-1, 0);
      else if (key === 'ArrowRight') setDirection(1, 0);
    } else if (key === ' ' || key === 'p' || key === 'P') {
      e.preventDefault();
      if (state === 'playing') pause();
      else if (state === 'paused') start();
    }
  });

  pauseBtn.addEventListener('click', function () {
    if (state === 'playing') pause();
    else if (state === 'paused') start();
  });

  restartBtn.addEventListener('click', function () {
    clearInterval(timer);
    reset();
    state = 'paused';
    pauseBtn.textContent = 'Resume';
    showOverlay('How to Play', 'Press an arrow key or tap <strong>Resume</strong> to start.<br>Eat the red food to grow. Avoid walls and yourself.', 'Resume');
  });

  overlayBtn.addEventListener('click', function () {
    if (state === 'over') {
      reset();
      state = 'paused';
      start();
    } else {
      start();
    }
  });

  // init
  reset();
  state = 'paused';
  pauseBtn.textContent = 'Resume';
  showOverlay('How to Play', 'Press an arrow key or tap <strong>Resume</strong> to start.<br>Eat the red food to grow. Avoid walls and yourself.', 'Resume');
})();
